diff --git a/mailnews/mime/src/nsStreamConverter.cpp b/mailnews/mime/src/nsStreamConverter.cpp
index 55fa607e43f..fb68f9f94a8 100644
--- a/mailnews/mime/src/nsStreamConverter.cpp
+++ b/mailnews/mime/src/nsStreamConverter.cpp
@@ -489,9 +489,11 @@ NS_IMETHODIMP nsStreamConverter::Init(nsIURI* aURI,
     if (!contractID.IsEmpty()) categoryName = contractID;

     mEmitter = do_CreateInstance(categoryName.get(), &rv);
-
-    if ((NS_FAILED(rv)) || (!mEmitter)) {
-      return NS_ERROR_OUT_OF_MEMORY;
+    if (!mEmitter) {
+      return NS_SUCCEEDED(rv) ? NS_ERROR_OUT_OF_MEMORY : rv;
+    }
+    if (NS_FAILED(rv)) {
+      return rv;
     }
   }

diff --git a/mailnews/protocols/exchange/src/ExchangeService.cpp b/mailnews/protocols/exchange/src/ExchangeService.cpp
index 46af3aa541d..04fd747ab91 100644
--- a/mailnews/protocols/exchange/src/ExchangeService.cpp
+++ b/mailnews/protocols/exchange/src/ExchangeService.cpp
@@ -121,9 +121,11 @@ NS_IMETHODIMP ExchangeService::GetUrlForUri(const nsACString& aMessageURI,
   NS_ENSURE_SUCCESS(rv, rv);

   nsAutoCString channelScheme;
-  if (scheme.EqualsLiteral("ews-message")) {
+  if (scheme.EqualsLiteral("ews-message") ||
+      scheme.EqualsLiteral("x-moz-ews")) {
     channelScheme.Assign("x-moz-ews");
-  } else if (scheme.EqualsLiteral("graph-message")) {
+  } else if (scheme.EqualsLiteral("graph-message") ||
+             scheme.EqualsLiteral("x-moz-graph")) {
     channelScheme.Assign("x-moz-graph");
   }

diff --git a/mailnews/protocols/exchange/test/unit/test_exchange_service.js b/mailnews/protocols/exchange/test/unit/test_exchange_service.js
new file mode 100644
index 00000000000..781ab041dae
--- /dev/null
+++ b/mailnews/protocols/exchange/test/unit/test_exchange_service.js
@@ -0,0 +1,47 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this file,
+ * You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+add_task(async function test_getUrlForUriEws() {
+  const service = Cc[
+    "@mozilla.org/messenger/messageservice;1?type=ews"
+  ].createInstance(Ci.nsIMsgMessageService);
+
+  const ewsMessageUrl = service.getUrlForUri(
+    "ews-message://name@localhost/some/folder",
+    null
+  );
+  Assert.equal(ewsMessageUrl.scheme, "x-moz-ews", "ews-message -> x-moz-ews");
+
+  const xMozEwsUrl = service.getUrlForUri(
+    "x-moz-ews://name@localhost/some/folder",
+    null
+  );
+  Assert.equal(xMozEwsUrl.scheme, "x-moz-ews", "x-moz-ews -> x-moz-ews");
+});
+
+add_task(async function test_getUrlForUriGraph() {
+  const service = Cc[
+    "@mozilla.org/messenger/messageservice;1?type=graph"
+  ].createInstance(Ci.nsIMsgMessageService);
+
+  const graphMessageUrl = service.getUrlForUri(
+    "graph-message://name@localhost/some/folder",
+    null
+  );
+  Assert.equal(
+    graphMessageUrl.scheme,
+    "x-moz-graph",
+    "graph-message -> x-moz-graph"
+  );
+
+  const xMozGraphUrl = service.getUrlForUri(
+    "x-moz-graph://name@localhost/some/folder",
+    null
+  );
+  Assert.equal(
+    xMozGraphUrl.scheme,
+    "x-moz-graph",
+    "x-moz-graph -> x-moz-graph"
+  );
+});
